create or replace function public.resolve_location_external_identity(p_source_dataset text,p_source_external_id text,p_latitude double precision,p_longitude double precision,p_name text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin if p_source_dataset is not null and p_source_external_id is not null then select id into v_id from public.locations where source_dataset=p_source_dataset and source_external_id=p_source_external_id limit 1; if v_id is not null then return v_id; end if; end if; select id into v_id from public.locations where is_active=true and latitude between p_latitude-0.0003 and p_latitude+0.0003 and longitude between p_longitude-0.0003 and p_longitude+0.0003 and (p_name is null or lower(trim(name))=lower(trim(p_name))) order by abs(latitude-p_latitude)+abs(longitude-p_longitude) limit 1; return v_id; end; $$;
